SemaphoreHandle_t rxSem;      /* binary, starts empty */

void UART_IRQHandler(void) {
    BaseType_t woken = pdFALSE;
    xSemaphoreGiveFromISR(rxSem, &woken); /* signal task */
    portYIELD_FROM_ISR(woken);
}

void rxTask(void *arg) {
    for (;;) {
        xSemaphoreTake(rxSem, portMAX_DELAY); /* block */
        process_rx_data();
    }
}

#define N 8
static item_t buf[N];
static unsigned in = 0, out = 0;          /* next slot to write / to read  */
static sem_t empty, full;                 /* sem_init: empty = N, full = 0 */
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void put(item_t x)
{
    sem_wait(&empty);                     /* 1. reserve a free slot        */
    pthread_mutex_lock(&lock);            /* 2. then lock the index        */
    buf[in] = x;  in = (in + 1) % N;
    pthread_mutex_unlock(&lock);
    sem_post(&full);                      /* 3. announce one more item     */
}

questions.questionText:
Assume C11. What does this program print?

#include <stdio.h>
#define N 8
static unsigned char buf[N];
static unsigned head = 0, tail = 0;

static int put(unsigned char c) {
    unsigned next = (head + 1) % N;
    if (next == tail) return 0;      /* full */
    buf[head] = c;
    head = next;
    return 1;
}

int main(void) {
    int ok = 0;
    for (int i = 0; i < 10; i++) ok += put((unsigned char)i);
    tail = 3;                          /* reader has taken 3 bytes */
    for (int i = 0; i < 5; i++) ok += put((unsigned char)i);
    printf("%d %u\n", ok, (head - tail + N) % N);
    return 0;
}

